package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.TypedFields.require;
import java.sql.SQLException;
import java.util.*;
import java.time.*;
import java.time.format.*;
import java.math.*;
/** Current-state age comes from retained transition evidence, never an arbitrary last edit. */
final class WorkflowInsights {
 private WorkflowInsights() {}
 static Map<String,Object> observed(Store.Db db,Map<String,Object> item,long instant)throws SQLException {
  String state=object(item.get("data")).get("state").toString();for(var event:db.all("SELECT action,created,detail FROM os_event WHERE record_id=? AND action IN ('created','updated') ORDER BY seq DESC LIMIT 500",item.get("sys_id"))){var detail=object(event.get("detail"));var after=object(detail.getOrDefault("after",map()));if(!state.equals(after.get("state")))return map("entered_at",null,"age_seconds",null);var before=object(detail.getOrDefault("before",map()));if(event.get("action").equals("created") || !state.equals(before.get("state"))){Long age=age(event.get("created").toString(),instant);return map("entered_at",age==null?null:event.get("created"),"age_seconds",age);}}
  return map("entered_at",null,"age_seconds",null);
 }
 static Long age(String value,long instant){try{long entered=LocalDateTime.parse(value,DateTimeFormatter.ofPattern("uuuu-MM-dd HH:mm:ss").withResolverStyle(ResolverStyle.STRICT)).toEpochSecond(ZoneOffset.UTC);return entered>instant?null:instant-entered;}catch(DateTimeParseException invalid){return null;}}
 static String hours(long seconds,long count){return BigDecimal.valueOf(seconds).divide(BigDecimal.valueOf(count).multiply(BigDecimal.valueOf(3600)),2,RoundingMode.HALF_UP).toPlainString();}
 static Map<String,Object> totals(List<Map<String,Object>> rows){long known=0,sum=0,max=0,over=0;for(var row:rows){if(row.get("age_seconds")!=null){long age=((Number)row.get("age_seconds")).longValue();known++;sum+=age;max=Math.max(max,age);}if(Boolean.TRUE.equals(row.get("above_threshold")))over++;}return map("count",rows.size(),"known",known,"unknown",rows.size()-known,"above_threshold",over,"mean_seconds",known==0?null:BigDecimal.valueOf(sum).divide(BigDecimal.valueOf(known),2,RoundingMode.HALF_UP).toPlainString(),"mean_hours",known==0?null:hours(sum,known),"max_seconds",known==0?null:max);}
 static Map<String,Object> page(Store.Db db,String table,Map<String,String> args,long instant)throws SQLException {
  if(!Set.of("admin","agent").contains(db.viewerRole))throw new Failure(403,"Staff access is required for workflow insights");require(Set.of("q","hours").containsAll(args.keySet()),"Use q and hours only");int threshold=Service.number(args.getOrDefault("hours","24"),0,87600);var schema=Service.schema(db,table);RecordPolicy.read(db,schema);var states=object(schema.get("states"));require(!states.isEmpty(),"Choose a stateful workflow table");if(!FieldAccess.allowed(db,schema,"state"))throw new Failure(403,"Current state access is required");String query=args.getOrDefault("q","");var selection=Service.selection(db,table,query,"");var selected=db.all("SELECT * FROM os_record WHERE "+selection.where()+" ORDER BY seq LIMIT 501",selection.values().toArray());require(selected.size()<=500,"Narrow the query to at most 500 records for a complete current-workload report");var rows=new ArrayList<Map<String,Object>>();var flow=object(schema.get("flow"));for(var item:selected){String state=object(item.get("data")).get("state").toString();if(((List<?>)flow.getOrDefault(state,List.of())).isEmpty())continue;var visible=FieldAccess.serialize(db,item);var row=observed(db,item,instant);Long age=(Long)row.get("age_seconds");row.putAll(map("record_id",item.get("sys_id"),"label",visible.getOrDefault("short_description","Record"),"state",state,"state_label",states.get(state),"age_hours",age==null?null:hours(age,1),"above_threshold",age!=null && age>=threshold*3600L));rows.add(row);}
  rows.sort(Comparator.<Map<String,Object>>comparingLong(row->row.get("age_seconds")==null?-1:((Number)row.get("age_seconds")).longValue()).reversed().thenComparing(row->row.get("record_id").toString()));var grouped=new TreeMap<String,List<Map<String,Object>>>();for(var row:rows)grouped.computeIfAbsent(row.get("state").toString(),key->new ArrayList<>()).add(row);var groups=new ArrayList<Map<String,Object>>();for(var entry:grouped.entrySet()){var group=totals(entry.getValue());group.putAll(map("state",entry.getKey(),"label",states.get(entry.getKey())));groups.add(group);}return map("table_name",table,"table_label",schema.get("label"),"q",query,"hours",threshold,"observed_at",Instant.ofEpochSecond(instant).toString(),"selected_count",selected.size(),"summary",totals(rows),"groups",groups,"records",rows);
 }
}
